using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
namespace F1Manager {
public class PodiumCard:Control {
    readonly Career state;readonly Row row;readonly int place;readonly Func<double> progress;
    public PodiumCard(Career career,Row result,int rank,Func<double> animation){state=career;row=result;place=rank;progress=animation;BackColor=Theme.Card;DoubleBuffered=true;}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;Color accent=place==1?Color.FromArgb(244,199,77):place==2?Color.FromArgb(201,212,226):Color.FromArgb(213,146,99);int rise=(int)((1-progress())*16);using(var path=Theme.Round(new Rectangle(0,rise,Width-1,Height-1-rise),14))using(var b=new SolidBrush(place==1?Color.FromArgb(48,39,29):Color.FromArgb(29,33,42)))using(var p=new Pen(Color.FromArgb(120,accent))){g.FillPath(b,path);g.DrawPath(p,path);}using(var font=new Font("Segoe UI",34,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(accent))g.DrawString(place.ToString("00"),font,b,17,14+rise);if(row==null){using(var font=new Font("Segoe UI",14,FontStyle.Regular,GraphicsUnit.Pixel))g.DrawString("Нет финишировавшего\nучастника",font,Brushes.White,20,150);return;}var person=Engine.Person(state,row.Id);var photo=DriverPhotos.Get(person);if(photo!=null)Theme.ImageFit(g,photo,new Rectangle(Width/2-70,57+rise,140,177));else {using(var p=new Pen(accent,3))g.DrawEllipse(p,Width/2-49,98+rise,98,98);using(var b=new SolidBrush(Theme.Red))g.FillRectangle(b,Width/2-42,131+rise,84,27);}if(row.Team<9)using(var path=Theme.Round(new Rectangle(Width-69,17+rise,54,43),6))g.FillPath(Brushes.White,path);Theme.ImageFit(g,TeamLogos.Get(row.Team),new Rectangle(Width-66,20+rise,48,37));using(var f=new Font("Segoe UI",20,FontStyle.Bold,GraphicsUnit.Pixel))TextRenderer.DrawText(g,person.Name,f,new Rectangle(14,245+rise,Width-28,33),Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",12,FontStyle.Regular,GraphicsUnit.Pixel))TextRenderer.DrawText(g,Engine.Team(state,row.Team).Name,f,new Rectangle(12,282+rise,Width-24,25),Theme.Muted,TextFormatFlags.HorizontalCenter);using(var f=new Font("Segoe UI",15,FontStyle.Bold,GraphicsUnit.Pixel))TextRenderer.DrawText(g,row.Points>0?row.Points+" очков":ManagerForm.LapFormat(row.Time),f,new Rectangle(12,319+rise,Width-24,28),accent,TextFormatFlags.HorizontalCenter);}
}
public class PodiumOverlay:GameOverlay {
    internal readonly SoftButton ContinueButton=new SoftButton{Text="Продолжить",Primary=true};
    public event Action Continued;
    readonly PodiumCard[] cards=new PodiumCard[3];
    internal readonly string SessionName;internal readonly Row[] Winners;
    protected override Size SheetSize {get{return new Size(1040,650);}}
    public PodiumOverlay(Career state,SessionResult result,int round,int year,bool animated):base(animated){SessionName=result.Name;bool qualifying=result.Name.StartsWith("Q")||result.Name.StartsWith("SQ");Winners=result.Rows.Where(r=>!r.Dnf&&(qualifying?r.Best>0&&r.Best<99999:r.Time>0)).OrderBy(r=>r.Position).Take(3).ToArray();string title=qualifying?(result.Name.EndsWith("3")?"ПОУЛ-ПОЗИШН":"ЛИДЕРЫ "+result.Name):result.Name=="Спринт"?"ПОДИУМ СПРИНТА":"ПОДИУМ ГРАН-ПРИ";LabelAt(Sheet,title,32,22,970,43,29,true,Color.White);LabelAt(Sheet,year+"  /  "+Data.Tracks[round].Country+"  /  "+result.Name,34,76,965,28,14);if(Winners.Length==0)LabelAt(Sheet,qualifying?"Никто не установил время. Полные результаты сохранены.":"Ни один пилот не финишировал. Результаты сходов сохранены.",32,119,965,36,14,false,Theme.Red);int[] order={2,1,3};for(int i=0;i<3;i++){int rank=order[i];var winner=Winners.Length>=rank?Winners[rank-1]:null;cards[i]=new PodiumCard(state,winner,rank,()=>Animated?Theme.Ease((Clock.Elapsed.TotalSeconds-.05*rank)/.2):1);Sheet.Controls.Add(cards[i]);}Sheet.Controls.Add(ContinueButton);ContinueButton.Click+=(o,e)=>Cancel();Sheet.Resize+=(o,e)=>LayoutCards();LayoutCards();}
    void LayoutCards(){int w=(Sheet.Width-88)/3;for(int i=0;i<3;i++)if(cards[i]!=null)cards[i].Bounds=new Rectangle(32+i*(w+12),i==1?145:167,w,366);ContinueButton.Bounds=new Rectangle(Sheet.Width-302,Sheet.Height-64,270,43);}
    protected override void Advance(){foreach(var c in cards)c.Invalidate();}
    public override void Cancel(){if(!Closing&&Continued!=null)Continued();}
}
public class EngineeringOverlay:GameOverlay {
    internal readonly SoftButton ContinueButton=new SoftButton{Text="Вернуться к команде",Primary=true};
    public event Action Continued;public event Action<int> Browse;
    public EngineeringReport Report;readonly Panel upgrades=new Panel{AutoScroll=true,BackColor=Theme.Card};
    protected override Size SheetSize {get{return new Size(1040,650);}}
    public EngineeringOverlay(Career state,EngineeringReport report,int index,bool animated):base(animated){Report=report;LabelAt(Sheet,"ИНЖЕНЕРНЫЙ ОТЧЁТ",32,21,970,40,27,true,Color.White);LabelAt(Sheet,report.Year+" / "+report.Track+" / Этап "+(report.Round+1),33,68,970,27,14);LabelAt(Sheet,"Болид на трассе: P"+report.OverallRank+" из "+state.Teams.Count+"  •  "+report.Layout,33,103,970,29,14,true,Theme.Red);for(int i=0;i<10;i++){int col=i/5,row=i%5,x=32+col*494,y=148+row*37;LabelAt(Sheet,CarModel.Names[i],x,y,270,29,13);LabelAt(Sheet,report.Values[i].ToString("0.0")+"  "+report.Change[i].ToString("+0.00;-0.00;—"),x+269,y,139,29,13,true,Color.White);LabelAt(Sheet,"P"+report.Ranks[i],x+414,y,60,29,14,true,Theme.Red);}LabelAt(Sheet,"ПРОВЕРКА НОВИНОК",33,346,970,28,13,true,Color.White);upgrades.Bounds=new Rectangle(32,383,976,170);Sheet.Controls.Add(upgrades);if(report.Upgrades.Count==0)LabelAt(upgrades,"Новых деталей для проверки нет. Выше — состояние болида и изменения с прошлого отчёта.",12,12,920,65,14);int top=0;foreach(var trial in report.Upgrades){var part=Data.Parts.First(p=>p.Key==trial.Key);var card=new RoundedPanel{BackColor=Color.FromArgb(31,35,44),Bounds=new Rectangle(0,top,948,94)};card.Controls.Add(new PartPicture(trial.Key){Bounds=new Rectangle(10,13,100,65)});LabelAt(card,part.Name+(trial.Version>0?" v"+trial.Version:""),122,9,520,25,16,true,Color.White);LabelAt(card,trial.Status,635,11,296,45,13,true,trial.ActualGain<=.01?Color.FromArgb(255,111,117):Color.FromArgb(96,219,164));LabelAt(card,trial.BenchFailed?"Стендовые испытания провалены. Деталь не использовалась в заезде.":"Эффективность: "+(100*trial.ActualGain/Math.Max(.001,trial.ExpectedGain)).ToString("0")+"% от расчёта  •  "+string.Join("  /  ",Enumerable.Range(0,10).Where(i=>Math.Abs(trial.Delta[i])>.001).Take(3).Select(i=>CarModel.Names[i]+" "+trial.Delta[i].ToString("+0.00;-0.00;0"))),122,42,803,44,12);upgrades.Controls.Add(card);top+=103;}var previous=new SoftButton{Text="‹ Прошлый",Bounds=new Rectangle(32,586,160,43),Enabled=index>0};var next=new SoftButton{Text="Следующий ›",Bounds=new Rectangle(207,586,160,43),Enabled=index<state.EngineeringReports.Count-1};previous.Click+=(o,e)=>{if(Browse!=null)Browse(-1);};next.Click+=(o,e)=>{if(Browse!=null)Browse(1);};Sheet.Controls.Add(previous);Sheet.Controls.Add(next);ContinueButton.Bounds=new Rectangle(718,586,290,43);Sheet.Controls.Add(ContinueButton);ContinueButton.Click+=(o,e)=>Cancel();}
    public override void Cancel(){if(!Closing&&Continued!=null)Continued();}
}
public partial class ManagerForm {
    void PresentSession(string name,int round,int year){bool qualify=name.StartsWith("Q")||name.StartsWith("SQ");if(!qualify&&name!="Гонка"&&name!="Спринт"){Notify(name+": результаты готовы.");return;}var result=name=="Гонка"?State.Archive.Last().Sessions.Last():State.Weekend.Results.Last();var podium=new PodiumOverlay(State,result,round,year,Preferences.Animations);podium.Continued+=()=>CloseOverlay(()=>{if(name=="Гонка"&&State.EngineeringReports.Count>0)ShowEngineeringReport(State.EngineeringReports.Last());});ShowOverlay(podium);}
    internal void ShowEngineeringReport(EngineeringReport report){if(activeOverlay!=null)return;int index=State.EngineeringReports.IndexOf(report);var overlay=new EngineeringOverlay(State,report,index,Preferences.Animations);overlay.Continued+=()=>CloseOverlay(null);overlay.Browse+=direction=>CloseOverlay(()=>ShowEngineeringReport(State.EngineeringReports[index+direction]));ShowOverlay(overlay);}
}
}
